1	package com.example.starter.tank;
2	
3	import com.example.starter.idempotent.IdempotencyService;
4	import com.example.starter.idempotent.ReplayResult;
5	import com.example.starter.station.Station;
6	import com.example.starter.station.StationRepository;
7	import com.example.starter.web.BusinessRejectedException;
8	import com.example.starter.web.ResourceNotFoundException;
9	import com.example.starter.web.VersionConflictException;
10	import com.example.starter.web.dto.TankCancelRequest;
11	import com.example.starter.web.dto.TankCancelResponse;
12	import com.example.starter.web.dto.TankPlanRequest;
13	import com.example.starter.web.dto.TankPlanResponse;
14	import com.example.starter.web.dto.TankReceiptRequest;
15	import com.example.starter.web.dto.TankReceiptResponse;
16	import com.example.starter.web.dto.TankRefillRequest;
17	import com.example.starter.web.dto.TankRefillResponse;
18	import com.example.starter.web.dto.TankRegisterRequest;
19	import com.example.starter.web.dto.TankRegisterResponse;
20	import com.example.starter.web.dto.TankView;
21	import org.springframework.dao.DuplicateKeyException;
22	import org.springframework.stereotype.Service;
23	
24	import java.math.BigDecimal;
25	import java.math.RoundingMode;
26	import java.time.LocalDateTime;
27	import java.util.ArrayList;
28	import java.util.List;
29	
30	/**
31	 * 储罐交接台账：登记、受控加注计划（预占/回执/取消）、双人确认补液入账。
32	 *
33	 * <ul>
34	 *   <li>登记：0≤安全储备&lt;容量，0≤期初余额≤容量，数量至多三位小数千克，
35	 *       一个门站至多绑定一个储罐；未绑定储罐的旧门站行为不变；</li>
36	 *   <li>计划：先预占所需量，预占后可用量（余额−预占）不得低于安全储备，恰等允许；
37	 *       低于则生成待补液事件且不下发加注（BLOCKED），不伪报加注成功；</li>
38	 *   <li>回执：预占转实际消耗并释放未用部分，实际量不得大于预占；
39	 *       重复回执（同量）返回首次执行结果，不重复扣量；</li>
40	 *   <li>取消：只释放尚未执行的预占；已执行计划不可取消；</li>
41	 *   <li>补液：唯一运输批号、两名不同交接人、浓度在许可闭区间（门站目标浓度±容差）、
42	 *       加入后不超容量（恰等允许），全部满足才原子入账并关闭可满足的待补液事件；
43	 *       仅关闭事件，不因一次入账自动重发旧加注命令；</li>
44	 *   <li>守恒：余额=期初+补液−消耗、预占=未执行预占合计，全部由台账分录勾稽，
45	 *       数值一律按规范值（compareTo）比较；</li>
46	 *   <li>并发：全部变更在储罐行锁内串行裁决，版本从 1 开始、成功变更加 1，
47	 *       业务、版本与幂等结果同事务提交，失败回滚不占幂等键。</li>
48	 * </ul>
49	 */
50	@Service
51	public class TankService {
52	
53	    private static final BigDecimal ZERO = BigDecimal.ZERO;
54	
55	    private final StationRepository stationRepository;
56	    private final TankRepository tankRepository;
57	    private final TankPlanRepository planRepository;
58	    private final TankRefillRepository refillRepository;
59	    private final TankRefillEventRepository eventRepository;
60	    private final TankLedgerRepository ledgerRepository;
61	    private final IdempotencyService idempotencyService;
62	
63	    public TankService(StationRepository stationRepository,
64	                       TankRepository tankRepository,
65	                       TankPlanRepository planRepository,
66	                       TankRefillRepository refillRepository,
67	                       TankRefillEventRepository eventRepository,
68	                       TankLedgerRepository ledgerRepository,
69	                       IdempotencyService idempotencyService) {
70	        this.stationRepository = stationRepository;
71	        this.tankRepository = tankRepository;
72	        this.planRepository = planRepository;
73	        this.refillRepository = refillRepository;
74	        this.eventRepository = eventRepository;
75	        this.ledgerRepository = ledgerRepository;
76	        this.idempotencyService = idempotencyService;
77	    }
78	
79	    // ---------------------------------------------------------------- 登记
80	
81	    public TankRegisterResponse register(TankRegisterRequest request) {
82	        Station station = stationRepository.findByCode(request.stationCode())
83	                .orElseThrow(() -> new ResourceNotFoundException(
84	                        "station not found: " + request.stationCode()));
85	        ReplayResult<TankRegisterResponse> replay = idempotencyService.run(
86	                request.requestId(), station.id(), "TANK_REGISTER", request, 200,
87	                () -> doRegister(station, request), TankRegisterResponse.class);
88	        return replay.result();
89	    }
90	
91	    private TankRegisterResponse doRegister(Station station, TankRegisterRequest request) {
92	        BigDecimal capacity = requireScale3(request.capacityKg(), "capacityKg");
93	        BigDecimal safety = requireScale3(request.safetyReserveKg(), "safetyReserveKg");
94	        BigDecimal balance = requireScale3(request.initialBalanceKg(), "initialBalanceKg");
95	        if (safety.compareTo(capacity) >= 0) {
96	            throw new IllegalArgumentException(
97	                    "safetyReserveKg must be less than capacityKg (0 <= safety reserve < capacity)");
98	        }
99	        if (balance.compareTo(capacity) > 0) {
100	            throw new IllegalArgumentException("initialBalanceKg must not exceed capacityKg");
101	        }
102	        Long tankId;
103	        try {
104	            tankId = tankRepository.insert(station.id(), request.tankCode(), capacity, safety, balance);
105	        } catch (DuplicateKeyException duplicate) {
106	            throw new BusinessRejectedException(
107	                    "tank code already used or station already bound: " + request.tankCode());
108	        }
109	        ledgerRepository.insert(tankId, "REGISTER", balance, ZERO, balance, ZERO,
110	                "REGISTER", null, request.requestId(), request.registeredAt());
111	        Tank tank = tankRepository.findById(tankId).orElseThrow();
112	        return new TankRegisterResponse(tank.id(), station.stationCode(), tank.tankCode(),
113	                tank.capacityKg(), tank.safetyReserveKg(), tank.balanceKg(), tank.reservedKg(),
114	                tank.version(), false);
115	    }
116	
117	    // ---------------------------------------------------------------- 加注计划
118	
119	    public TankPlanResponse createPlan(TankPlanRequest request) {
120	        Tank tank = tankRepository.findByCode(request.tankCode())
121	                .orElseThrow(() -> new ResourceNotFoundException(
122	                        "tank not found: " + request.tankCode()));
123	        ReplayResult<TankPlanResponse> replay = idempotencyService.run(
124	                request.requestId(), tank.stationId(), "TANK_PLAN", request, 200,
125	                () -> doCreatePlan(tank.id(), request), TankPlanResponse.class);
126	        return replay.result();
127	    }
128	
129	    private TankPlanResponse doCreatePlan(Long tankId, TankPlanRequest request) {
130	        BigDecimal required = requireScale3(request.requiredQtyKg(), "requiredQtyKg");
131	        Tank tank = lockTank(tankId);
132	        checkVersion(tank, request.expectedVersion());
133	
134	        BigDecimal available = tank.availableKg();
135	        if (available.subtract(required).compareTo(tank.safetyReserveKg()) >= 0) {
136	            // 预占后可用量不低于安全储备（恰等允许）：预占并下发
137	            BigDecimal reservedAfter = tank.reservedKg().add(required);
138	            long newVersion = bumpVersion(tank, tank.balanceKg(), reservedAfter);
139	            Long planId = planRepository.insert(tank.id(), request.requestId(),
140	                    request.plannedAt(), required, "RESERVED");
141	            ledgerRepository.insert(tank.id(), "RESERVE", ZERO, required,
142	                    tank.balanceKg(), reservedAfter, "PLAN", planId,
143	                    request.requestId(), request.plannedAt());
144	            return new TankPlanResponse(planId, tank.id(), "RESERVED", true, required,
145	                    tank.balanceKg(), reservedAfter, tank.balanceKg().subtract(reservedAfter),
146	                    null, newVersion, false);
147	        }
148	
149	        // 预占后可用量低于安全储备：生成待补液事件，不下发加注
150	        long newVersion = bumpVersion(tank, tank.balanceKg(), tank.reservedKg());
151	        Long planId = planRepository.insert(tank.id(), request.requestId(),
152	                request.plannedAt(), required, "BLOCKED");
153	        BigDecimal deficit = required.subtract(available.subtract(tank.safetyReserveKg()));
154	        Long eventId = eventRepository.insert(tank.id(), "PLAN", planId, required, deficit);
155	        return new TankPlanResponse(planId, tank.id(), "BLOCKED", false, required,
156	                tank.balanceKg(), tank.reservedKg(), available, eventId, newVersion, false);
157	    }
158	
159	    // ---------------------------------------------------------------- 执行回执
160	
161	    public TankReceiptResponse receipt(TankReceiptRequest request) {
162	        TankPlan plan = planRepository.findById(request.planId())
163	                .orElseThrow(() -> new ResourceNotFoundException(
164	                        "plan not found: " + request.planId()));
165	        Tank tank = tankRepository.findById(plan.tankId()).orElseThrow();
166	        ReplayResult<TankReceiptResponse> replay = idempotencyService.run(
167	                request.requestId(), tank.stationId(), "TANK_RECEIPT", request, 200,
168	                () -> doReceipt(tank.id(), request), TankReceiptResponse.class);
169	        return replay.result();
170	    }
171	
172	    private TankReceiptResponse doReceipt(Long tankId, TankReceiptRequest request) {
173	        BigDecimal actual = requireScale3(request.actualQtyKg(), "actualQtyKg");
174	        Tank tank = lockTank(tankId);
175	        checkVersion(tank, request.expectedVersion());
176	        TankPlan plan = planRepository.findByIdForUpdate(request.planId()).orElseThrow();
177	
178	        switch (plan.status()) {
179	            case "RESERVED" -> {
180	                if (actual.compareTo(plan.requiredQtyKg()) > 0) {
181	                    throw new BusinessRejectedException(
182	                            "actual quantity exceeds reserved: " + actual.toPlainString()
183	                                    + " > " + plan.requiredQtyKg().toPlainString());
184	                }
185	                BigDecimal unused = plan.requiredQtyKg().subtract(actual);
186	                BigDecimal balanceAfter = tank.balanceKg().subtract(actual);
187	                BigDecimal reservedAfter = tank.reservedKg().subtract(plan.requiredQtyKg());
188	                long newVersion = bumpVersion(tank, balanceAfter, reservedAfter);
189	                planRepository.markExecuted(plan.id(), actual, request.executedAt());
190	                if (actual.signum() > 0) {
191	                    // 预占转实际消耗：余额与预占同步扣减
192	                    ledgerRepository.insert(tank.id(), "CONSUME", actual.negate(), actual.negate(),
193	                            balanceAfter, tank.reservedKg().subtract(actual),
194	                            "RECEIPT", plan.id(), request.requestId(), request.executedAt());
195	                }
196	                if (unused.signum() > 0) {
197	                    // 释放未用部分
198	                    ledgerRepository.insert(tank.id(), "RELEASE", ZERO, unused.negate(),
199	                            balanceAfter, reservedAfter,
200	                            "RECEIPT", plan.id(), request.requestId(), request.executedAt());
201	                }
202	                return new TankReceiptResponse(plan.id(), tank.id(), "EXECUTED", actual, unused,
203	                        balanceAfter, reservedAfter, newVersion, false);
204	            }
205	            case "EXECUTED" -> {
206	                if (actual.compareTo(plan.actualQtyKg()) == 0) {
207	                    // 重复回执（同量）：返回首次执行结果，不重复扣量、不变更版本
208	                    return new TankReceiptResponse(plan.id(), tank.id(), "EXECUTED",
209	                            plan.actualQtyKg(), plan.requiredQtyKg().subtract(plan.actualQtyKg()),
210	                            tank.balanceKg(), tank.reservedKg(), tank.version(), false);
211	                }
212	                throw new BusinessRejectedException(
213	                        "plan already executed with quantity " + plan.actualQtyKg().toPlainString());
214	            }
215	            case "CANCELLED" -> throw new BusinessRejectedException("plan already cancelled");
216	            default -> throw new BusinessRejectedException("plan not dispatched (blocked)");
217	        }
218	    }
219	
220	    // ---------------------------------------------------------------- 取消
221	
222	    public TankCancelResponse cancel(TankCancelRequest request) {
223	        TankPlan plan = planRepository.findById(request.planId())
224	                .orElseThrow(() -> new ResourceNotFoundException(
225	                        "plan not found: " + request.planId()));
226	        Tank tank = tankRepository.findById(plan.tankId()).orElseThrow();
227	        ReplayResult<TankCancelResponse> replay = idempotencyService.run(
228	                request.requestId(), tank.stationId(), "TANK_CANCEL", request, 200,
229	                () -> doCancel(tank.id(), request), TankCancelResponse.class);
230	        return replay.result();
231	    }
232	
233	    private TankCancelResponse doCancel(Long tankId, TankCancelRequest request) {
234	        Tank tank = lockTank(tankId);
235	        checkVersion(tank, request.expectedVersion());
236	        TankPlan plan = planRepository.findByIdForUpdate(request.planId()).orElseThrow();
237	
238	        switch (plan.status()) {
239	            case "RESERVED" -> {
240	                // 只释放尚未执行的预占
241	                BigDecimal reservedAfter = tank.reservedKg().subtract(plan.requiredQtyKg());
242	                long newVersion = bumpVersion(tank, tank.balanceKg(), reservedAfter);
243	                planRepository.markCancelled(plan.id(), request.cancelledAt());
244	                ledgerRepository.insert(tank.id(), "RELEASE", ZERO, plan.requiredQtyKg().negate(),
245	                        tank.balanceKg(), reservedAfter, "CANCEL", plan.id(),
246	                        request.requestId(), request.cancelledAt());
247	                return new TankCancelResponse(plan.id(), tank.id(), "CANCELLED",
248	                        plan.requiredQtyKg(), tank.balanceKg(), reservedAfter, newVersion, false);
249	            }
250	            case "CANCELLED" -> {
251	                // 重复取消：预占已释放，返回当前状态，不重复返还
252	                return new TankCancelResponse(plan.id(), tank.id(), "CANCELLED", ZERO,
253	                        tank.balanceKg(), tank.reservedKg(), tank.version(), false);
254	            }
255	            case "EXECUTED" -> throw new BusinessRejectedException("plan already executed");
256	            default -> throw new BusinessRejectedException("plan not dispatched (blocked)");
257	        }
258	    }
259	
260	    // ---------------------------------------------------------------- 补液
261	
262	    public TankRefillResponse refill(TankRefillRequest request) {
263	        Tank tank = tankRepository.findByCode(request.tankCode())
264	                .orElseThrow(() -> new ResourceNotFoundException(
265	                        "tank not found: " + request.tankCode()));
266	        ReplayResult<TankRefillResponse> replay = idempotencyService.run(
267	                request.requestId(), tank.stationId(), "TANK_REFILL", request, 200,
268	                () -> doRefill(tank.id(), request), TankRefillResponse.class);
269	        return replay.result();
270	    }
271	
272	    private TankRefillResponse doRefill(Long tankId, TankRefillRequest request) {
273	        BigDecimal quantity = requireScale3(request.quantityKg(), "quantityKg");
274	        BigDecimal concentration = requireScale3(request.concentrationMgM3(), "concentrationMgM3");
275	        Tank tank = lockTank(tankId);
276	        checkVersion(tank, request.expectedVersion());
277	
278	        String firstOperator = request.operators().get(0);
279	        String secondOperator = request.operators().get(1);
280	        if (firstOperator.equals(secondOperator)) {
281	            throw new BusinessRejectedException("refill requires two different handover operators");
282	        }
283	
284	        Station station = stationRepository.findById(tank.stationId()).orElseThrow();
285	        BigDecimal tolerance = station.targetConcentrationMgM3()
286	                .multiply(station.concentrationTolerancePct())
287	                .divide(BigDecimal.valueOf(100), 3, RoundingMode.HALF_UP);
288	        BigDecimal lowerBound = station.targetConcentrationMgM3().subtract(tolerance);
289	        BigDecimal upperBound = station.targetConcentrationMgM3().add(tolerance);
290	        // 许可闭区间：恰在边界允许入账
291	        if (concentration.compareTo(lowerBound) < 0 || concentration.compareTo(upperBound) > 0) {
292	            throw new BusinessRejectedException(
293	                    "concentration out of permitted range [" + lowerBound.toPlainString()
294	                            + ", " + upperBound.toPlainString() + "]: " + concentration.toPlainString());
295	        }
296	
297	        BigDecimal balanceAfter = tank.balanceKg().add(quantity);
298	        // 加入后不超容量，恰等容量允许
299	        if (balanceAfter.compareTo(tank.capacityKg()) > 0) {
300	            throw new BusinessRejectedException(
301	                    "refill would exceed tank capacity: " + balanceAfter.toPlainString()
302	                            + " > " + tank.capacityKg().toPlainString());
303	        }
304	
305	        Long refillId;
306	        try {
307	            refillId = refillRepository.insert(tank.id(), request.requestId(),
308	                    request.transportBatchNo(), quantity, concentration,
309	                    firstOperator, secondOperator, request.receivedAt());
310	        } catch (DuplicateKeyException duplicate) {
311	            throw new BusinessRejectedException(
312	                    "transport batch already posted: " + request.transportBatchNo());
313	        }
314	        long newVersion = bumpVersion(tank, balanceAfter, tank.reservedKg());
315	        ledgerRepository.insert(tank.id(), "REFILL", quantity, ZERO, balanceAfter,
316	                tank.reservedKg(), "REFILL", refillId, request.requestId(), request.receivedAt());
317	
318	        // 关闭可满足的待补液事件：仅关闭，不因一次入账自动重发旧加注命令
319	        BigDecimal available = balanceAfter.subtract(tank.reservedKg());
320	        List<Long> closedEventIds = new ArrayList<>();
321	        for (TankRefillEvent event : eventRepository.findOpenForUpdate(tank.id())) {
322	            if (available.subtract(event.requiredQtyKg()).compareTo(tank.safetyReserveKg()) >= 0) {
323	                eventRepository.close(event.id(), refillId);
324	                closedEventIds.add(event.id());
325	            }
326	        }
327	        return new TankRefillResponse(refillId, tank.id(), request.transportBatchNo(), quantity,
328	                balanceAfter, tank.reservedKg(), available, closedEventIds, newVersion, false);
329	    }
330	
331	    // ---------------------------------------------------------------- 压力联动闸控
332	
333	    /**
334	     * 压力联动消耗闸控（与压力检测同事务）：绑定储罐的门站按可用量判定，
335	     * 不足时生成待补液事件并返回 false，调用方不得伪报加注成功；
336	     * 未绑定储罐的旧门站直接返回 true，行为不变。
337	     *
338	     * @return true 已扣减（或无需扣减）可下发加注；false 可用量不足未扣减
339	     */
340	    public boolean consumeForLinkage(Long stationId, BigDecimal doseKg, Long taskId,
341	                                     String requestId, LocalDateTime detectedAt) {
342	        Tank tank = tankRepository.findByStationIdForUpdate(stationId).orElse(null);
343	        if (tank == null || doseKg.signum() <= 0) {
344	            return true;
345	        }
346	        BigDecimal available = tank.availableKg();
347	        if (available.subtract(doseKg).compareTo(tank.safetyReserveKg()) >= 0) {
348	            BigDecimal balanceAfter = tank.balanceKg().subtract(doseKg);
349	            bumpVersion(tank, balanceAfter, tank.reservedKg());
350	            ledgerRepository.insert(tank.id(), "CONSUME", doseKg.negate(), ZERO,
351	                    balanceAfter, tank.reservedKg(), "PRESSURE", taskId, requestId, detectedAt);
352	            return true;
353	        }
354	        BigDecimal deficit = doseKg.subtract(available.subtract(tank.safetyReserveKg()));
355	        bumpVersion(tank, tank.balanceKg(), tank.reservedKg());
356	        eventRepository.insert(tank.id(), "PRESSURE", null, doseKg, deficit);
357	        return false;
358	    }
359	
360	    // ---------------------------------------------------------------- 查询
361	
362	    /**
363	     * 储罐台账视图：余额、预占、可用量与当前版本。
364	     */
365	    public TankView tankView(String tankCode) {
366	        Tank tank = tankRepository.findByCode(tankCode)
