3	CREATE TABLE IF NOT EXISTS station (
4	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
5	    station_code VARCHAR(64) NOT NULL,
6	    name VARCHAR(128) NOT NULL,
7	    pressure_low_limit_mpa DECIMAL(10,4) NOT NULL,
8	    pressure_high_limit_mpa DECIMAL(10,4) NOT NULL,
9	    pressure_target_mpa DECIMAL(10,4) NOT NULL,
10	    target_concentration_mg_m3 DECIMAL(10,3) NOT NULL,
11	    concentration_tolerance_pct DECIMAL(6,2) NOT NULL,
12	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
13	);
