36	
37	CREATE TABLE IF NOT EXISTS valve_state (
38	    station_id BIGINT PRIMARY KEY,
39	    injection_locked BOOLEAN NOT NULL DEFAULT FALSE,
40	    alarm_active BOOLEAN NOT NULL DEFAULT FALSE,
41	    breach_count INT NOT NULL DEFAULT 0,
42	    current_injection_rate_mg_m3 DECIMAL(10,3) NOT NULL DEFAULT 20,
43	    current_pressure_mpa DECIMAL(10,4),
44	    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
45	);
46	COMMENT ON COLUMN valve_state.injection_locked IS '加注阀锁定状态：TRUE锁定须双人复开';
47	COMMENT ON COLUMN valve_state.alarm_active IS '浓度连续越限告警状态';
48	COMMENT ON COLUMN valve_state.breach_count IS '当前连续越限检测次数，合格即归零，达2锁阀';
49	COMMENT ON COLUMN valve_state.current_injection_rate_mg_m3 IS '当前加注速率折算末端浓度mg/m3';
50	COMMENT ON COLUMN valve_state.current_pressure_mpa IS '最近一次联动后管网压力MPa，NULL未调节';
51	
52	CREATE TABLE IF NOT EXISTS odorant_reading (
53	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
54	    station_id BIGINT NOT NULL,
55	    request_id VARCHAR(64) NOT NULL,
56	    detected_at TIMESTAMP NOT NULL,
57	    gas_flow_m3 DECIMAL(14,3) NOT NULL,
58	    concentration_mg_m3 DECIMAL(10,3) NOT NULL,
59	    qualified BOOLEAN NOT NULL,
60	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
61	);
62	COMMENT ON COLUMN odorant_reading.detected_at IS '检测时刻（业务时间，Asia/Shanghai）';
63	COMMENT ON COLUMN odorant_reading.gas_flow_m3 IS '检测时段标况累计流量m3';
64	COMMENT ON COLUMN odorant_reading.concentration_mg_m3 IS '末端加臭剂实测浓度mg/m3';
65	COMMENT ON COLUMN odorant_reading.qualified IS '浓度是否在20mg/m3上下20%闭区间';
66	
67	CREATE TABLE IF NOT EXISTS pressure_reading (
68	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
69	    station_id BIGINT NOT NULL,
70	    request_id VARCHAR(64) NOT NULL,
71	    detected_at TIMESTAMP NOT NULL,
72	    pressure_mpa DECIMAL(10,4) NOT NULL,
73	    grade VARCHAR(16) NOT NULL,
74	    task_id BIGINT,
75	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
