91	);
92	COMMENT ON COLUMN lock_order.action IS 'LOCK锁阀/REOPEN复开，均须两名不同操作人';
93	COMMENT ON COLUMN lock_order.status IS 'PENDING待确认/CONFIRMED已生效';
94	COMMENT ON COLUMN lock_order.first_operator IS '第一名确认人工号，空表示系统触发待受理';
