129	
130	CREATE TABLE IF NOT EXISTS daily_close (
131	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
132	    station_id BIGINT NOT NULL,
133	    biz_date DATE NOT NULL,
134	    status VARCHAR(16) NOT NULL,
135	    total_flow_m3 DECIMAL(16,3) NOT NULL,
