151	CREATE TABLE IF NOT EXISTS late_event (
152	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
153	    station_id BIGINT NOT NULL,
154	    source_type VARCHAR(16) NOT NULL,
155	    request_id VARCHAR(64) NOT NULL,
156	    detected_at TIMESTAMP NOT NULL,
