                       String requestId, LocalDateTime bizAt) {
        jdbc.update("""
                        INSERT INTO tank_ledger
                            (tank_id, entry_type, balance_delta_kg, reserved_delta_kg,
                             balance_after_kg, reserved_after_kg, ref_type, ref_id,
