16	/**
17	 * 可复算服务：浓度曲线、压力链与消耗勾稽均可由原始数据重新计算核验。
18	 *
19	 * <p>复算仅依赖原始读数、门站限值与联动记录，重新执行闭区间判定与勾稽公式，
20	 * 不读取首次处理时缓存的判定结论。
21	 */
22	@Service
23	public class RecomputeService {
24	
25	    private static final BigDecimal ALLOWED_DEVIATION_PCT = new BigDecimal("3.0000");
26	
27	    private final StationRepository stationRepository;
28	    private final RecomputeRepository recomputeRepository;
29	    private final DailyCloseRepository dailyCloseRepository;
30	
31	    public RecomputeService(StationRepository stationRepository,
32	                            RecomputeRepository recomputeRepository,
33	                            DailyCloseRepository dailyCloseRepository) {
34	        this.stationRepository = stationRepository;
35	        this.recomputeRepository = recomputeRepository;
36	        this.dailyCloseRepository = dailyCloseRepository;
37	    }
38	
39	    /**
40	     * 复算指定业务日期的浓度曲线（含闭区间边界重新判定）。
41	     */
42	    @Transactional(readOnly = true)
43	    public List<CurvePoint> concentrationCurve(String stationCode, LocalDate bizDate) {
44	        Station station = loadStation(stationCode);
45	        BigDecimal[] bounds = concentrationBounds(station);
46	        return recomputeRepository.findOdorantReadings(station.id(), bizDate).stream()
47	                .map(r -> new CurvePoint(
