    @Test
    void refillCapacityBoundary() {
        register("TK01", "1000", "100", "900");
        // 恰等容量允许
        assertBd("1000", refill("TK01", "RF-1", 1, "B-1", "100", "20.000").balanceKg());
        // 超容量拒绝
        assertThrows(BusinessRejectedException.class,
