package com.example.starter.web.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 受控加注计划请求：先预占所需量，预占后可用量不得低于安全储备（恰等允许）。
 *
 * @param tankCode        储罐编码
 * @param requestId       幂等键
 * @param expectedVersion 储罐乐观锁期望版本
 * @param plannedAt       计划时刻（业务时间，精确时刻参与指纹）
 * @param requiredQtyKg   计划预占量 kg，须为正，至多三位小数
 */
public record TankPlanRequest(
        @NotBlank String tankCode,
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotNull LocalDateTime plannedAt,
        @NotNull @DecimalMin("0.001") BigDecimal requiredQtyKg) {
}

package com.example.starter.web.dto;

import com.example.starter.idempotent.Replayable;

import java.math.BigDecimal;

/**
 * 加注计划受理结果。
 *
 * @param planId           计划ID
 * @param tankId           储罐ID
 * @param status           RESERVED 已预占并下发 / BLOCKED 可用量低于安全储备未下发
 * @param dispatched       是否已下发加注（BLOCKED 为 false，不得伪报加注成功）
 * @param requiredQtyKg    计划预占量 kg
 * @param balanceKg        操作后余额 kg
 * @param reservedKg       操作后预占中数量 kg
 * @param availableKg      操作后可用量 kg = 余额 − 预占
 * @param refillEventId    生成的待补液事件ID，未触发为 null
 * @param version          操作后储罐版本
 * @param idempotentReplay 是否为同键同参重放
 */
public record TankPlanResponse(
        Long planId,
        Long tankId,
        String status,
        boolean dispatched,
        BigDecimal requiredQtyKg,
        BigDecimal balanceKg,
        BigDecimal reservedKg,
        BigDecimal availableKg,
        Long refillEventId,
        long version,
        boolean idempotentReplay) implements Replayable<TankPlanResponse> {

    @Override
    public TankPlanResponse withReplay(boolean replay) {
        return new TankPlanResponse(planId, tankId, status, dispatched, requiredQtyKg, balanceKg,
                reservedKg, availableKg, refillEventId, version, replay);
    }
}

package com.example.starter.web.dto;

import com.example.starter.idempotent.Replayable;

import java.math.BigDecimal;
import java.util.List;

/**
 * 补液入账结果：原子入账并关闭可满足的待补液事件（不自动重发旧加注命令）。
 *
 * @param refillId         补液单ID
 * @param tankId           储罐ID
 * @param transportBatchNo 运输批号
 * @param quantityKg       入账数量 kg
 * @param balanceKg        入账后余额 kg
 * @param reservedKg       入账后预占中数量 kg
 * @param availableKg      入账后可用量 kg
 * @param closedEventIds   本次入账关闭的待补液事件ID集合
 * @param version          入账后储罐版本
 * @param idempotentReplay 是否为同键同参重放
 */
public record TankRefillResponse(
        Long refillId,
        Long tankId,
        String transportBatchNo,
        BigDecimal quantityKg,
        BigDecimal balanceKg,
        BigDecimal reservedKg,
        BigDecimal availableKg,
        List<Long> closedEventIds,
        long version,
        boolean idempotentReplay) implements Replayable<TankRefillResponse> {

    @Override
    public TankRefillResponse withReplay(boolean replay) {
        return new TankRefillResponse(refillId, tankId, transportBatchNo, quantityKg, balanceKg,
                reservedKg, availableKg, closedEventIds, version, replay);
    }
}

